pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzzed parameters: an address actor and a second guess bytes32 newHash
    function testFuzz_property(address actor, bytes32 newHash) public {
        // admissible domain: actor should not be address(0) and must be different from contract deployer
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // fund the actor so they can pay 1 ether
        vm.deal(actor, 2 ether);

        // first lockInGuess by actor must succeed and reserve their slot
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked("first")));

        // attempt a second lockInGuess by the same actor paying 1 ether
        // For the correct contract this should revert (guard prevents multiple guesses).
        // For the mutant it will succeed and overwrite the previous guess
        bool ok;
        vm.prank(actor);
        try c.lockInGuess{value: 1 ether}(newHash) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property: The reference contract rejects a second lockInGuess from the same caller (ok == false for all inputs).
        // The mutant removes that require, so there exist inputs (the fuzzer may find one) where ok == true.
        assertTrue(!ok);
    }
}

