pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // Fuzzed parameter: an address that will act as the caller
    function testFuzz_property(address caller) public {
        // 1. keep caller within EOA space the fuzzer can control, but avoid zero address
        vm.assume(caller != address(0));
        // give caller at least 1 ether to send
        vm.deal(caller, 2 ether);

        // Prepare a non-zero hash to lock in
        bytes32 guessHash = keccak256(abi.encodePacked("guess", caller));

        // Act as the caller and call lockInGuess with exactly 1 ether
        vm.startPrank(caller);
        bool ok;
        try c.lockInGuess{value: 1 ether}(guessHash) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The universal property: for any admissible caller that successfully calls lockInGuess (ok == true),
        // the stored guess observed via the public getter must equal the submitted guess and thus be non-zero.
        // The mutant that writes the block first can transiently leave guess zero and thus will sometimes fail this.
        if (ok) {
            // c.guesses is a public mapping of Guess structs, so getter exists: guesses(address) returns (uint, bytes32)
            (, bytes32 stored) = c.guesses(caller);
            assertTrue(stored != bytes32(0));
        } else {
            // If the call reverted, still satisfy property vacuously by asserting ok is false or nothing;
            // but we must make exactly one assertTrue in the test, so assert that ok is true OR stored nonzero.
            // However the required single assert must express the property: when ok==true, stored!=0.
            // To satisfy the single assert requirement unconditionally, assert that either the call succeeded and stored!=0,
            // or the call reverted (ok==false). This is equivalent to: ok == false || stored != 0
            // We need to obtain stored only if possible; calling getter is always allowed.
            (, bytes32 stored) = c.guesses(caller);
            assertTrue(!ok || stored != bytes32(0));
        }
    }
}

